test('requestCompleted receives null as the error of a successful request', async t => {
  t.plan(2)

  const errors = []
  class RecordingLogController extends LogController {
    requestCompleted (error, request, reply, metadata) {
      errors.push(error)
      super.requestCompleted(error, request, reply, metadata)
    }
  }

  const fastify = Fastify({ logController: new RecordingLogController() })
  t.after(() => fastify.close())

  fastify.get('/', (req, reply) => { reply.send({ hello: 'world' }) })
  // the onResponse hook runner is a separate path to requestCompleted
  fastify.get('/hooked', {
    onResponse: (req, reply, done) => { done() }
  }, (req, reply) => { reply.send({ hello: 'world' }) })

  await fastify.inject('/')
  await fastify.inject('/hooked')

  t.assert.strictEqual(errors[0], null)
  t.assert.strictEqual(errors[1], null)
})

